using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace McvsOffline.Server.Core.Content
{
    /// <summary>
    /// Where modules get data from:
    /// <list type="bullet">
    /// <item><b>Game files</b> from the player's own data pack (e.g. Config/crmpreconfiguration.json, the CRM
    /// default, read at runtime and never redistributed — ARCHITECTURE §3 "CRM").</item>
    /// <item><b>Our content</b>: files generated by tools/content-gen into server/Content (compiled into the DLL),
    /// optionally overridden by files in &lt;data&gt;/content/ so players can tweak them without a rebuild.</item>
    /// </list>
    /// </summary>
    public interface IContentProvider
    {
        /// <summary>The player's data pack, or null when none was configured or found.</summary>
        DataPack DataPack { get; }

        bool TryReadGameFile(string logicalPath, out byte[] data);

        bool TryReadGameText(string logicalPath, out string text);

        /// <summary>Our content by relative name ("offline_store.json"); the &lt;data&gt;/content override wins.</summary>
        bool TryReadContent(string name, out byte[] data);

        bool TryReadContentText(string name, out string text);

        /// <summary>Names of the built-in content files (overrides not included).</summary>
        List<string> ContentNames { get; }
    }

    public sealed class ContentProvider : IContentProvider
    {
        private readonly string overrideDirectory;
        private readonly Log log;
        private readonly object gate = new object();
        private bool warnedNoPack;

        /// <param name="dataPack">The player's data pack (may be null).</param>
        /// <param name="overrideDirectory">Directory whose files override built-in content (may be null).</param>
        public ContentProvider(DataPack dataPack, string overrideDirectory, Log log)
        {
            DataPack = dataPack;
            this.overrideDirectory = string.IsNullOrEmpty(overrideDirectory) ? null : Path.GetFullPath(overrideDirectory);
            this.log = log ?? Log.Null;
        }

        public DataPack DataPack { get; private set; }

        public List<string> ContentNames
        {
            get { return new List<string>(BuiltInContent.All.Keys); }
        }

        public bool TryReadGameFile(string logicalPath, out byte[] data)
        {
            data = null;
            if (DataPack == null)
            {
                lock (gate)
                {
                    if (!warnedNoPack)
                    {
                        warnedNoPack = true;
                        log.Warn("no data pack configured: game file '" + logicalPath + "' (and later ones) unavailable");
                    }
                }
                return false;
            }
            if (DataPack.TryRead(logicalPath, out data)) return true;
            log.Warn("game file '" + logicalPath + "' not found in " + DataPack.DataDirectory);
            return false;
        }

        public bool TryReadGameText(string logicalPath, out string text)
        {
            byte[] data;
            text = null;
            if (!TryReadGameFile(logicalPath, out data)) return false;
            text = DecodeText(data);
            return true;
        }

        public bool TryReadContent(string name, out byte[] data)
        {
            data = null;
            if (string.IsNullOrEmpty(name)) return false;
            string normalized = name.Replace('\\', '/').TrimStart('/');
            if (normalized.IndexOf("..", StringComparison.Ordinal) >= 0) return false;
            if (overrideDirectory != null)
            {
                string file = Path.Combine(overrideDirectory, normalized.Replace('/', Path.DirectorySeparatorChar));
                if (File.Exists(file))
                {
                    data = File.ReadAllBytes(file);
                    return true;
                }
            }
            byte[] builtIn;
            if (BuiltInContent.All.TryGetValue(normalized, out builtIn))
            {
                data = (byte[])builtIn.Clone(); // callers may modify their copy; the built-in bytes are shared
                return true;
            }
            return false;
        }

        public bool TryReadContentText(string name, out string text)
        {
            byte[] data;
            text = null;
            if (!TryReadContent(name, out data)) return false;
            text = DecodeText(data);
            return true;
        }

        private static string DecodeText(byte[] data)
        {
            string text = Encoding.UTF8.GetString(data);
            if (text.Length > 0 && text[0] == '\uFEFF') text = text.Substring(1);
            return text;
        }
    }

    /// <summary>
    /// Content compiled into the assembly from server/Content. The generated half of this class (obj/.../McvsContent.g.cs,
    /// written by server/build/McvsOffline.Server.Shared.props) implements <c>Register</c>.
    /// </summary>
    internal static partial class BuiltInContent
    {
        private static readonly object Gate = new object();
        private static Dictionary<string, byte[]> all;

        public static Dictionary<string, byte[]> All
        {
            get
            {
                lock (Gate)
                {
                    if (all == null)
                    {
                        var text = new Dictionary<string, string>(StringComparer.Ordinal);
                        var base64 = new Dictionary<string, string>(StringComparer.Ordinal);
                        Register(text, base64);
                        var map = new Dictionary<string, byte[]>(StringComparer.Ordinal);
                        foreach (var kv in text) map[kv.Key] = new UTF8Encoding(false).GetBytes(kv.Value);
                        foreach (var kv in base64) map[kv.Key] = Convert.FromBase64String(kv.Value);
                        all = map;
                    }
                    return all;
                }
            }
        }

        static partial void Register(Dictionary<string, string> text, Dictionary<string, string> base64);
    }
}
